      SUBROUTINE FNDMAG(KNAME)CC     FIND MAGNETS OF THE GIVEN TYPECC     LIST OF COMMON BLOCKSC      INCLUDE 'TRNSPRT_PARAM.CIN'      INCLUDE 'DATA0A.CIN'      INCLUDE 'DATA1A.CIN'      INCLUDE 'DATA1D.CIN'      INCLUDE 'DATA2A.CIN'      INCLUDE 'INDPAR.CIN'CC     LOCAL VARIABLESC      CHARACTER*15    KNAME      EQUIVALENCE     (FAKE,LAKE)      EXTERNAL        IDATACC-----------------------------------------------------------------------C      IF (NEL .EQ. 0) GO TO 200      DO 20 NN = 1, NEL      IEL = ISTOR(NN)      NTYPE = IDATA(IEL)      IF (KNAME .NE. LBTYP(NN)) GO TO 20      IF (NTYPE .NE. 3 .AND. NTYPE .NE. 4 .AND. NTYPE .NE. 5     1    .AND. NTYPE .NE. 11 .AND. NTYPE .NE. 18 .AND. NTYPE .NE. 19     2    .AND. NTYPE .NE. 20 .AND. NTYPE .NE. 25 .AND. NTYPE .NE. 28     3    .AND. NTYPE .NE. 29 .AND. NTYPE .NE. 35 .AND. NTYPE .NE. 36)     4    GO TO 20      CALL SKETCH(NN)      IF (NTYPE .EQ. 3) ILB = 2      IF (NTYPE .EQ. 5) ILB = 7      IF (NTYPE .EQ. 11) ILB = 6      IF (NTYPE .EQ. 18) ILB = 6      IF (NTYPE .EQ. 19) ILB = 4      IF (NTYPE .EQ. 20) ILB = 2      IF (NTYPE .EQ. 25) ILB = 6      IF (NTYPE .EQ. 28 .OR. NTYPE .EQ. 29) ILB = 25      IF (NTYPE .EQ. 35 .OR. NTYPE .EQ. 36) ILB = 6      ILB = IPTOJ(ILB)      IF (ILB .NE. 0) THEN        IADR = IEL + ILB        LAKE = NUM        DATA(IADR) = FAKE      ENDIF   20 CONTINUE  200 RETURN      END